result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/booleanNetwork.test.ts", "content": "import { describe, expect, it } from 'vitest';
import {
  buildSuccessorMap,
  findAttractors,
  formatState,
  NUM_STATES,
  successor,
  toDot,
} from '../src/booleanNetwork.js';

describe('Boolean network A\'=B, B\'=A, C\'=A|D, D\'=C', () => {
  it('updates single genes correctly', () => {
    expect(successor(0b0000)).toBe(0b0000); // fixed point
    expect(successor(0b0011)).toBe(0b0011); // fixed point
    expect(successor(0b1111)).toBe(0b1111); // fixed point
    expect(successor(0b1000)).toBe(0b0100); // A=1,B=0,C=0,D=0 -> A'=0,B'=1,C'=1,D'=0
  });

  it('builds a successor map over exactly all 16 states', () => {
    const map = buildSuccessorMap();
    expect(map).toHaveLength(NUM_STATES);
    for (const target of map) {
      expect(target).toBeGreaterThanOrEqual(0);
      expect(target).toBeLessThan(NUM_STATES);
    }
  });

  it('finds exactly 6 attractors of the expected shapes', () => {
    const attractors = findAttractors();
    expect(attractors).toHaveLength(6);

    const shapes = attractors.map((a) =>
      a.cycle.length === 1 ? `fp ${formatState(a.cycle[0])}` : `cycle ${a.cycle.map(formatState).join('->')}`,
    );
    expect(shapes.sort()).toEqual(
      [
        'cycle 0001->0010',
        'cycle 0110->1001',
        'cycle 0111->1011',
        'fp 0000',
        'fp 0011',
        'fp 1111',
      ].sort(),
    );
  });

  it('every attractor is closed under the dynamics', () => {
    for (const { cycle } of findAttractors()) {
      for (const s of cycle) {
        expect(cycle).toContain(successor(s));
      }
    }
  });

  it('basin sizes sum to 16 and basins partition all states', () => {
    const attractors = findAttractors();
    const total = attractors.reduce((acc, a) => acc + a.basin.length, 0);
    expect(total).toBe(NUM_STATES);

    const seen = new Set<number>();
    for (const a of attractors) {
      for (const s of a.basin) {
        expect(seen.has(s)).toBe(false);
        seen.add(s);
      }
    }
    expect(seen.size).toBe(NUM_STATES);
  });

  it('each basin contains its own attractor', () => {
    for (const { cycle, basin } of findAttractors()) {
      for (const s of cycle) expect(basin).toContain(s);
    }
  });

  it('exports a DOT graph with exactly one edge per state', () => {
    const dot = toDot();
    expect(dot.startsWith('digraph')).toBe(true);
    const edges = dot.split('\n').filter((l) => l.includes('->'));
    expect(edges).toHaveLength(NUM_STATES);
    // Each state appears as an edge source exactly once.
    for (let s = 0; s < NUM_STATES; s++) {
      expect(edges.filter((e) => e.includes(`"${formatState(s)}" ->`))).toHaveLength(1);
    }
    expect(dot).toContain('"0111" -> "1011";');
    expect(dot).toContain('"0010" -> "0001";');
  });
});
"})
