result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/booleanNetwork.ts", "content": "/**
 * Synchronous Boolean network:
 *   A' = B
 *   B' = A
 *   C' = A OR D
 *   D' = C
 *
 * A state is encoded as a 4-bit integer with bit order ABCD,
 * i.e. bit 3 = A, bit 2 = B, bit 1 = C, bit 0 = D.
 */

export const NUM_STATES = 16;

/** Read a single gene from a state. gene: 0=A, 1=B, 2=C, 3=D */
export function getGene(state: number, gene: number): 0 | 1 {
  return ((state >> (3 - gene)) & 1) as 0 | 1;
}

/** Pretty-print a state as "ABCD". */
export function formatState(state: number): string {
  return state.toString(2).padStart(4, '0');
}

/** Apply the synchronous update rule once. */
export function successor(state: number): number {
  const A = getGene(state, 0);
  const B = getGene(state, 1);
  const C = getGene(state, 2);
  const D = getGene(state, 3);
  return ((B << 3) | (A << 2) | ((A | D) << 1) | C) & 0b1111;
}

/** Successor map for all 16 states, indexed by state. */
export function buildSuccessorMap(): number[] {
  return Array.from({ length: NUM_STATES }, (_, s) => successor(s));
}

export interface Attractor {
  /** States on the attractor cycle, in trajectory order. Length 1 = fixed point. */
  cycle: number[];
  /** All states whose trajectory eventually enters the cycle (cycle included). */
  basin: number[];
}

/**
 * Detect all attractors and their basins by forward trajectories.
 * Each of the 16 states is assigned to exactly one attractor basin,
 * so the basin sizes always sum to NUM_STATES.
 */
export function findAttractors(): Attractor[] {
  const succ = buildSuccessorMap();

  // attractorIdOf[state]: index into `cycles` once the trajectory's attractor is known
  const attractorOf = new Map<number, number>();
  const cycles: number[][] = [];

  for (let start = 0; start < NUM_STATES; start++) {
    if (attractorOf.has(start)) continue; // already classified

    // Walk until we hit a state that is already classified (fast path)
    // or revisit a state in the current walk (new cycle found).
    const path: number[] = [];
    const positionInPath = new Map<number, number>();
    let s = start;
    while (!attractorOf.has(s) && !positionInPath.has(s)) {
      positionInPath.set(s, path.length);
      path.push(s);
      s = succ[s];
    }

    if (positionInPath.has(s)) {
      // New attractor: the cycle is the tail of the walked path.
      const from = positionInPath.get(s)!;
      const cycle = path.slice(from);
      const id = cycles.push(cycle) - 1;
      for (const c of cycle) attractorOf.set(c, id);
      // Everything before `from` is transient leading to this attractor...
      for (let i = 0; i < from; i++) attractorOf.set(path[i], id);
    } else {
      // Reached an already-known attractor; whole path flows into it.
      const id = attractorOf.get(s)!;
      for (const p of path) attractorOf.set(p, id);
    }
  }

  const basins: number[][] = Array.from({ length: cycles.length }, () => []);
  for (let st = 0; st < NUM_STATES; st++) {
    basins[attractorOf.get(st)!].push(st);
  }

  return cycles.map((cycle, i) => ({ cycle, basin: basins[i] }));
}

/** DOT-format state transition graph ("0000" -> "0100"; style). */
export function toDot(): string {
  const lines = ['digraph booleanNetwork {'];
  for (let s = 0; s < NUM_STATES; s++) {
    lines.push(`  "${formatState(s)}" -> "${formatState(successor(s))}";`);
  }
  lines.push('}');
  return lines.join('\n');
}
"})
